INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (70712, 'spa', 'Cítara, lira', 'Instrumento de cuerdas pulsadas, específicamente la κιθάρα o lira griega, que produce melodía al ser rasgada. Pablo la utiliza como ilustración del habla inteligible (1 Co 14:7), mientras que Apocalipsis presenta a los redimidos tocando cítaras ante el trono (Ap 5:8; 14:2; 15:2). El español ''cítara'' preserva directamente la etimología griega, confirmando que se trata de la lira clásica y no de un arpa moderna.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (70715, 'spa', 'Cilicia (provincia)', 'La provincia romana de Cilicia en el sureste de Asia Menor, cuya ciudad principal, Tarso, fue la patria de Pablo. Las ocho apariciones neotestamentarias se concentran en Hechos y Gálatas, vinculando la región con la identidad de Pablo (Hch 21:39; 22:3), la geografía de la iglesia primitiva (Hch 15:23, 41) y sus viajes posteriores a la conversión (Gá 1:21).');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (70717, 'spa', 'Canela, especia aromática', 'Se refiere a la especia canela, un producto comercial de gran valor en la antigüedad. Su aparición en la lista de mercancías de la Babilonia caída en Apocalipsis subraya el apego de la ciudad condenada al lujo y al placer sensorial: ni las especias más costosas pueden evitar el juicio divino ni comprar redención ante la destrucción.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (70718, 'spa', 'Estar en peligro', 'Hallarse en peligro o en situación de riesgo, ya sea físico, social o legal. En Lucas 8:23 el peligro es una tempestad que amenaza la vida; en Hechos 19:27 la amenaza es económica y religiosa (el culto a Artemisa pierde credibilidad); en Hechos 19:40 se trata de riesgo legal (ser acusados de sedición); y en 1 Corintios 15:30 Pablo habla de su constante peligro de muerte por la fe.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (70719, 'spa', 'Peligro, riesgo', 'Peligro, riesgo o situación amenazante para la vida o la seguridad. κίνδυνος abarca tanto el riesgo abstracto como circunstancias concretas de amenaza. El catálogo de peligros de Pablo en 2 Corintios 11:26 emplea el término ocho veces — peligros de ríos, ladrones, compatriotas, gentiles, ciudad, desierto, mar y falsos hermanos — convirtiéndolo en el pasaje definitorio del NT.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (70721, 'spa', 'Menear, sacudir', 'Gesto físico de sacudir o menear, específicamente la cabeza en señal de burla. En la crucifixión (Mt 27:39; Mr 15:29), los que pasaban meneaban la cabeza en son de escarnio. Este gesto evoca la tradición del Salmo 22:7, donde los que desprecian al justo sufriente sacuden la cabeza con desdén.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (70722, 'spa', 'Agitar, conmover', 'Agitación figurada o incitación social: provocar alboroto o conmoción cívica. En Hechos 21:30 toda la ciudad «se conmovió», y en Hechos 24:5 se acusa a Pablo de ser un agitador. Tanto el griego pasivo ἐκινήθη como el español «se conmovió» transmiten que la perturbación se propaga por la comunidad como una ola, pasando de la provocación individual al tumulto colectivo.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (70723, 'spa', 'Mover, estar en movimiento', 'Movimiento físico general o estado de estar en movimiento. El sermón de Pablo en el Areópago (Hch 17:28) lo emplea existencialmente: «en él vivimos, nos movemos y existimos», captando el movimiento creatural sostenido por Dios. En Mt 23:4 el sentido es más cotidiano: la falta de voluntad para «mover» un dedo y aliviar cargas pesadas.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (70726, 'spa', 'Remover, desplazar', 'Quitar o desplazar algo de una posición establecida. En Ap 2:5 Cristo advierte que «removerá» el candelero de Éfeso de su lugar, y en Ap 6:14 los montes e islas «fueron movidos» de sus posiciones en una convulsión apocalíptica. El español «moveré» y «fueron movidos» subrayan la finalidad: una vez desplazado, el objeto no vuelve a su lugar anterior.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (70728, 'spa', 'Movimiento o agitación', 'Se refiere al movimiento o agitación, particularmente del agua. En el relato de Betesda (donde está atestiguado textualmente), esta perturbación periódica de las aguas del estanque se consideraba con propiedades curativas, atrayendo a enfermos y discapacitados que esperaban el movimiento que pudiera traerles sanidad, una esperanza que Jesús trasciende al sanar directamente.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (70729, 'spa', 'Nombre del padre de Saúl', 'Nombre propio del padre del rey Saúl, de la tribu de Benjamín. Este marcador genealógico en el discurso de Pablo establece las credenciales tribales legítimas de Saúl, mientras crea una resonancia sutil con Pablo mismo: ambos benjaminitas llamados Saulo, uno un rey fracasado, el otro apóstol del verdadero Rey.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (70730, 'spa', 'Rama — Una rama o ramaje literal de arbol, como las ramas maduras del grano de m', 'Rama — Una rama o ramaje literal de arbol, como las ramas maduras del grano de mostaza donde se posan las aves (Mt 13:32; Mc 4:32), la rama tierna de la higuera que senala la proximidad del verano (Mt 24:32; Mc 13:28), y las ramas cortadas y esparcidas ante Jesus durante la entrada triunfal en Jerusalen (Mt 21:8; Mc 11:8).');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (70734, 'spa', 'Llorar, lamentar', 'Derramar lagrimas como expresion externa de dolor, tristeza, duelo o angustia espiritual. El verbo abarca todo el registro emocional del llanto en el NT: el dolor inconsolable de Raquel por sus hijos (Mt 2:18, citando Jer 31:15), las lagrimas amargas de arrepentimiento de Pedro (Mt 26:75; Lc 22:62), los que lloraban por la hija de Jairo (Mc 5:38-39) y Maria Magdalena llorando ante la tumba vacia (Jn 20:11-15).');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (70755, 'spa', 'Fragmento, pedazo partido', 'Fragmento o pedazo partido de pan, sobras recogidas tras una alimentación milagrosa. Derivado de κλάω (''partir''), κλάσμα aparece en el NT solo en estos relatos: los cinco mil (Mt 14:20; Jn 6:12-13) y los cuatro mil (Mt 15:37; Mr 8:8). La orden de recoger los fragmentos «para que nada se pierda» (Jn 6:12) los eleva a símbolo de abundancia divina.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (70758, 'spa', 'Isla cerca de Creta', 'Nombre de una pequeña isla al sur de Creta que brindó refugio momentáneo durante el viaje del naufragio de Pablo. Este respiro temporal permitió preparativos cruciales antes de que la tormenta azotara con toda su fuerza, un momento de calma relativa en el vívido relato de Lucas que muestra tanto realismo náutico como la providencia divina preservando a Pablo para llegar a Roma.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (70759, 'spa', 'Cristiana en Roma', 'Mujer cristiana en Roma que se unió al envío de saludos a Timoteo a través de la última carta de Pablo. Aunque no sabemos nada más de su historia, su inclusión en el círculo de colaboradores de Pablo da testimonio del papel vital de las mujeres en la vida y misión de la iglesia primitiva.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (70760, 'spa', 'Nombre romano', 'Claudio, nombre romano referido a dos individuos distintos en Hechos. El emperador Claudio se menciona en 11:28 (durante cuyo reinado Agabo predijo una hambruna) y en 18:2 (quien expulsó a los judíos de Roma, provocando que Aquila y Priscila se trasladasen a Corinto). Hechos 23:26 se refiere a Claudio Lisias, el tribuno romano que comandaba la guarnición en Jerusalén y protegió a Pablo.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (70761, 'spa', 'Llanto, lamento', 'Llanto o clamor audible que expresa dolor o angustia intensos, más allá de lágrimas silenciosas. Su uso más distintivo en el NT es la fórmula de Jesús «habrá llanto y crujir de dientes» (Mt 8:12; 13:42, 50; 22:13; 25:30; Lc 13:28), que evoca el clamor de los excluidos del reino. En Mateo 2:18 resuena el duelo inconsolable de Raquel.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (70762, 'spa', 'Partir el pan', 'Partir el pan: partir el pan con las manos, refiriéndose al acto físico de dividir un pan en porciones para repartirlo. Se usa exclusivamente con pan en el Nuevo Testamento: durante los milagros de alimentación (Mateo 14:19; Marcos 8:6, 8:19), en la institución de la Cena del Señor (Mateo 26:26; Lucas 22:19; 1 Corintios 11:24) y en las comidas comunitarias de la iglesia primitiva (Hechos 2:46; 20:7). El español ''partir'' conserva el núcleo de acción física, pero el matiz sacramental es inconfundible en cada contexto neotestamentario.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (70768, 'spa', 'Llave de autoridad', 'Llave como instrumento de autoridad y acceso, utilizada exclusivamente en contextos metafóricos y simbólicos en el NT. Jesús otorga a Pedro las ''llaves del reino de los cielos'' (Matt 16:19), reprende a los doctores de la ley por quitar ''la llave del conocimiento'' (Luke 11:52), y declara en Apocalipsis que posee ''las llaves de la Muerte y del Hades'' (Rev 1:18) y ''la llave de David'' (Rev 3:7). El ángel del abismo igualmente recibe una llave (Rev 9:1; 20:1), confirmando el patrón de autoridad delegada sobre un dominio.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (70770, 'spa', 'Cerrar físicamente (cerrar una barrera física como una puerta o un portón, restr', 'Cerrar físicamente (cerrar una barrera física como una puerta o un portón, restringiendo el paso o el acceso a un espacio. Jesús dice a sus discípulos que ''cierren la puerta'' para la oración privada (Mt 6:6); el dueño de casa en la parábola ya ha ''cerrado la puerta'' (Lc 11:7); la puerta del novio se ''cierra'' contra las vírgenes insensatas (Mt 25:10); y los discípulos se reúnen a puertas ''cerradas'' por miedo (Jn 20:19, 20:26).)');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (70771, 'spa', 'Cerrar con autoridad, vedar el acceso (cerrar con autoridad o vedar el acceso en', 'Cerrar con autoridad, vedar el acceso (cerrar con autoridad o vedar el acceso en sentido figurado, cósmico o espiritual. El sujeto ejerce autoridad divina o delegada sobre lo que se abre o cierra: los fariseos ''cierran el reino de los cielos'' (Mt 23:13), Cristo ''abre y nadie cierra, cierra y nadie abre'' (Ap 3:7), el cielo se ''cierra'' contra la lluvia (Lc 4:25, Ap 11:6), el abismo es cerrado con llave (Ap 20:3), y una persona ''cierra sus entrañas'' de compasión (1 Jn 3:17).)');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (70783, 'spa', 'Hurtos o robos', 'Se refiere a actos de hurto o a bienes robados. En la secuencia de plagas de Apocalipsis, la negativa de la humanidad a arrepentirse de los robos —junto con otros pecados graves— demuestra la dureza de corazón que persiste aun bajo el juicio divino, evocando la resistencia reiterada de Faraón ante catástrofes cada vez mayores.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (70784, 'spa', 'Discípulo camino a Emaús', 'Uno de los dos discípulos a quienes el Jesús resucitado se unió en el camino a Emaús, enseñándoles desde las Escrituras antes de revelarse en el partir del pan. Aunque sabemos poco más de Cleofas, su encuentro encarna el reconocimiento transformador de Cristo que convierte la desesperanza en testimonio ardiente.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (70785, 'spa', 'Crédito y honor', 'Se refiere al crédito, honor o reputación loable que se obtiene mediante las acciones propias. Pedro emplea este término retóricamente para distinguir entre sufrir las consecuencias del pecado (lo cual no merece alabanza) y soportar con paciencia el sufrimiento injusto (lo cual halla gracia ante Dios y confiere verdadera gloria, siguiendo el ejemplo de Cristo).');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (70786, 'spa', 'Ladrón (persona que roba con sigilo o astucia y no mediante violencia abierta', 'Ladrón (persona que roba con sigilo o astucia y no mediante violencia abierta. En uso literal, los ladrones irrumpen en casas o almacenes para llevarse objetos de valor (Mt 6:19-20; Lc 12:33). En sentido figurado, Jesús califica de ladrón al falso pastor (Jn 10:1) y Judas es identificado como quien sustraía de la bolsa común (Jn 12:6). El uso teológicamente más cargado compara la parusía de Cristo con la llegada sorpresiva de un ladrón (Mt 24:43; 1 Ts 5:2, 4; 2 P 3:10; Ap 3:3; 16:15).)');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (70788, 'spa', 'Robar', 'Robar: tomar la propiedad ajena de manera ilícita, hurtar o sustraer. La palabra aparece en citas directas del mandamiento del Decálogo que prohíbe el robo (Mateo 19:18; Marcos 10:19; Romanos 13:9), en la enseñanza de Jesús sobre los ladrones que perforan paredes para robar tesoros terrenales (Mateo 6:19-20), en la conspiración para afirmar que los discípulos robaron el cuerpo de Jesús (Mateo 27:64; 28:13) y en Juan 10:10 donde el ladrón viene solo para robar. Las traducciones en distintos idiomas convergen en un solo sentido semántico unificado.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (70797, 'spa', 'Pámpano, sarmiento', 'Rama o brote de vid que crece del tronco principal de la planta. Aparece exclusivamente en la alegoría de la vid de Jesús (Jn 15:2, 4, 5, 6), donde el término enfatiza la total dependencia del pámpano respecto a la vid para recibir vida y dar fruto. El español ''pámpano'' — término vitícola técnico para el brote verde de la vid — corresponde con precisión a la especificidad del griego.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (70798, 'spa', 'Nombre propio: Clemente', 'Colaborador de Pablo en el ministerio del evangelio, elogiado junto con otros fieles obreros en Filipos. Aunque las contribuciones específicas de Clemente no quedaron registradas, la seguridad que Pablo da de que su nombre está escrito en el libro de la vida lo eleva de la oscuridad histórica a una significación eterna en los registros de Dios.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (70799, 'spa', 'Heredar, recibir como herencia (recibir u obtener algo como herencia, asignación', 'Heredar, recibir como herencia (recibir u obtener algo como herencia, asignación o posesión prometida, aplicado tanto a legados terrenales como a las grandes bendiciones teológicas de la vida eterna, el reino y la nueva creación. La pregunta sinóptica ''¿qué debo hacer para heredar la vida eterna?'' (Mc 10:17; Lc 10:25; 18:18) enmarca la salvación como herencia divinamente asignada. Jesús promete que los mansos ''heredarán la tierra'' (Mt 5:5) y en el juicio final invita a los benditos a ''heredar el reino'' (Mt 25:34).)');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (70809, 'spa', 'Herencia', 'Herencia: la propiedad, porción o promesa recibida por derecho de sucesión o por concesión divina. Abarca tanto lo concreto (una herencia familiar disputada en Lucas 12:13; la promesa de la tierra a Abraham en Hechos 7:5; Hebreos 11:8) como lo espiritual (la herencia celestial del creyente en Efesios 1:14, 18; 1 Pedro 1:4; la herencia del reino en Gálatas 5:21). La parábola de los labradores malvados (Mateo 21:38; Marcos 12:7; Lucas 20:14) gira en torno al intento de apoderarse de la herencia del hijo, fusionando lo terrenal con lo teológico.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (70810, 'spa', 'Heredero (quien recibe una herencia)', 'Heredero (quien recibe una herencia). Persona que hereda propiedad, estatus o una promesa divina. Se aplica literalmente al hijo en la parábola de los labradores de la viña (Mt 21:38; Mc 12:7; Lc 20:14), cuyo asesinato dramatiza el rechazo de Israel al mensajero de Dios. Se usa teológicamente de los creyentes que heredan la salvación y las promesas hechas a Abraham (Ro 4:13-14; Gá 3:29; Heb 1:2).');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (70812, 'spa', 'Suerte (para echar a suertes)', 'Suerte (para echar a suertes). El objeto concreto que se lanzaba o se sacaba para tomar decisiones, o el acto mismo de echar suertes. Los cuatro Evangelios registran que los soldados echaron suertes (κλῆρον) por las vestiduras de Jesús en la crucifixión (Mt 27:35; Jn 19:24), y Hechos 1:26 describe a los apóstoles echando suertes para reemplazar a Judas.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (70813, 'spa', 'Herencia, patrimonio asignado', 'Herencia, patrimonio asignado. La extensión teológica donde lo que Dios asigna a su pueblo se convierte en su porción espiritual o escatológica. En Hechos 26:18 la comisión de Pablo incluye conceder a los gentiles ''una herencia entre los santificados,'' y Colosenses 1:12 habla de compartir ''la herencia de los santos en luz.''');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (70814, 'spa', 'Parte, porción (rol asignado)', 'Parte, porción (rol asignado). La extensión metafórica de ''lo que le toca a uno por suerte'' hacia el lugar asignado dentro de un grupo o empresa. Judas ''fue contado y le tocó en suerte este ministerio'' (Hch 1:17), y a Simón el Mago se le dice que no tiene ''ni parte ni suerte en este asunto'' (Hch 8:21).');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (70817, 'spa', 'Herencia por designación divina', 'Indica ser hecho heredero u obtener una herencia, con matices de asignación o designación divina. Dentro del lenguaje exaltado de Efesios sobre los propósitos de Dios en Cristo, este verbo afirma que los creyentes han recibido una herencia no por casualidad ni por mérito, sino por el plan predeterminado de Dios, designados para una porción en el reino cósmico de Cristo.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (70818, 'spa', 'Llamamiento, vocacion — El acto divino de convocar a las personas a la salvacion', 'Llamamiento, vocacion — El acto divino de convocar a las personas a la salvacion, la fe y la esperanza escatologica. Pablo habla de la ''esperanza de vuestro llamamiento'' (Ef 1:18), de su naturaleza irrevocable (Rom 11:29) y del humilde perfil social de aquellos a quienes Dios llama (1 Cor 1:26). Se exhorta a los creyentes a andar de manera digna de este llamamiento (Ef 4:1, 4; Fil 3:14; 2 Tes 1:11; 2 Pe 1:10).');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (70821, 'spa', 'Llamado (convocado/designado divinamente) — Convocado divinamente a la fe e inco', 'Llamado (convocado/designado divinamente) — Convocado divinamente a la fe e incorporado al pueblo de Dios. Los creyentes son ''santos llamados'' (Rom 1:7; 1 Cor 1:2), ''llamados conforme a su proposito'' (Rom 8:28), e identificados junto al Cordero como ''llamados, elegidos y fieles'' (Ap 17:14). La palabra subraya que la salvacion se origina en la iniciativa de Dios, no en la decision humana.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (70825, 'spa', 'Región o territorio', 'Región, distrito o territorio geográfico. Pablo emplea este término para describir las amplias áreas de su labor misionera: las «regiones de Acaya» en 2 Corintios 11:10, «las regiones de Siria y Cilicia» en Gálatas 1:21, y en Romanos 15:23 afirma que ya no tiene «lugar en estas regiones» del Mediterráneo oriental, indicando que su obra allí está completa y debe avanzar hacia el oeste, rumbo a España.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (70826, 'spa', 'Cama, lecho', 'Cama, lecho o camilla para dormir, reclinarse o transportar enfermos. El griego κλίνη (de κλίνω, ''reclinarse'') abarca desde una cama propiamente dicha hasta una estera portátil. Su aparición más memorable es en la sanación del paralítico, donde Jesús ordena «levántate, toma tu cama y anda» (Mt 9:2, 6), transformando el símbolo de invalidez en signo de restauración.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (70830, 'spa', 'Camilla o lecho portátil', 'Cama pequeña, camilla o estera portátil usada para dormir o transportar enfermos. En Lucas 5:19, 24 designa el «lecho pequeño» del paralítico que sus amigos llevaron hasta Jesús y que él mismo cargó tras ser sanado. Hechos 5:15 menciona a la gente colocando enfermos «en camas y camillas» en las calles, esperando que la sombra de Pedro los sanara. El término subraya la condición humilde de estos individuos.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (70831, 'spa', 'Inclinar, reclinar', 'Acostar, inclinar o reclinar: un gesto físico de descanso o reverencia. Jesús no tiene dónde ''recostar'' su cabeza (Mt 8:20; Lc 9:58); en su muerte ''inclinó'' la cabeza (Jn 19:30); las mujeres junto al sepulcro inclinan el rostro hacia el suelo (Lc 24:5). El significado básico es doblar o inclinarse hacia abajo.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (70832, 'spa', 'Declinar (del día)', 'Declinar o menguar, dicho del día que avanza hacia el atardecer. En Lucas 9:12 el día ''comenzaba a declinar'' y en Lucas 24:29 ''ya ha declinado''. Esta metáfora temporal extiende el sentido físico de ''inclinarse'' al paso del tiempo: el sol literalmente se inclina hacia el horizonte.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (70836, 'spa', 'Poner en fuga', 'Poner en fuga, derrotar: una metáfora militar donde la idea básica de hacer que algo ''ceda'' o ''se incline'' se convierte en hacer huir a ejércitos enemigos. Se usa en Hebreos 11:34, donde los héroes de la fe ''hicieron huir a ejércitos de extranjeros''. El español ''hicieron huir'' capta la fuerza causativa del verbo.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (70837, 'spa', 'Grupos de comensales', 'Se refiere a grupos organizados de personas dispuestas para compartir una comida. La disposición ordenada en grupos de cincuenta durante la alimentación de los cinco mil refleja tanto la distribución práctica del alimento como matices simbólicos del banquete mesiánico, donde Jesús provee pan abundante para su pueblo reunido en comunidad ordenada.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (70840, 'spa', 'Zarandeado por las olas', 'Describe el ser sacudido o azotado, particularmente por las olas del mar. Pablo emplea esta imagen marítima para ilustrar la inestabilidad teológica: creyentes inmaduros zarandeados por vientos cambiantes y oleajes de enseñanza engañosa, carentes del ancla y el lastre que provienen de crecer hacia Cristo mediante la verdad proclamada con amor.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (70841, 'spa', 'Nombre propio masculino', 'Esposo de una de las Marías que presenciaron la crucifixión de Jesús. Aunque no sabemos más de Clopas directamente, su identificación lo sitúa dentro del círculo íntimo de los seguidores de Jesús, y la presencia de su esposa al pie de la cruz testimonia la fidelidad de familiares y amigos durante la hora más sombría del Señor.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (70842, 'spa', 'Comezón de oír', 'Describe la picazón o el deseo de ser rascado, usado metafóricamente para oídos que pican: personas que acumulan maestros para satisfacer su ansia de mensajes agradables en vez de la verdad. Esta ''comezón'' representa una actitud superficial hacia la enseñanza, que privilegia la comodidad y la novedad por encima de las exigencias transformadoras de la auténtica proclamación del evangelio.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (70843, 'spa', 'Ciudad costera antigua', 'Ciudad costera del suroeste de Asia Menor a la que el barco de Pablo se acercó con dificultad durante su viaje a Roma. Este punto de referencia en la precisa narrativa geográfica de Lucas marca el inicio de la fase más peligrosa del viaje, cuando los vientos contrarios forzaron al barco a alejarse de la costa asiática hacia la ruta más expuesta que bordea Creta.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (70845, 'spa', 'El utero o cavidad materna, usado para referirse a la concepcion, el embarazo y ', 'El utero o cavidad materna, usado para referirse a la concepcion, el embarazo y el nacimiento. En hindi, garbh y kokh distinguen este sentido del digestivo, mientras que en espanol vientre y en aleman Bauch permanecen ambiguos. Pasajes clave incluyen Lucas 1:41-44 (el nino saltando en el vientre de Elisabet) y Mateo 19:12 (nacido del vientre materno). Catorce ocurrencias se agrupan claramente aqui.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (70846, 'spa', 'El estomago o abdomen fisico como organo de digestion y apetito', 'El estomago o abdomen fisico como organo de digestion y apetito. Usado en contextos de alimentacion, glotoneria e interior fisico: ''el dios de ellos es su vientre'' (Fil. 3:19), la comida que pasa por el estomago (Mt. 15:17; Mr. 7:19) y el vientre del gran pez en la tipologia de Jonas (Mt. 12:40). Nueve ocurrencias llevan este sentido.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (70851, 'spa', 'Morir (eufemismo)', 'Morir (eufemismo): Morir, expresado eufemísticamente como dormirse, usado especialmente de creyentes que esperan la resurrección. El español «durmieron/dormiremos» y el alemán «schlafen/schläft ein» conservan la metáfora del sueño sin lenguaje explícito de muerte, reflejando la ternura pastoral del NT. Este sentido domina el discurso paulino sobre la resurrección (1 Co 15:6, 18, 20, 51; 1 Ts 4:13-15), donde la metáfora no es mero adorno sino fundamento teológico.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (70853, 'spa', 'Dormir (literal, físico)', 'Dormir (literal, físico): Estar en un estado de sueño físico ordinario o descanso. El francés «dormir/endormir» y el español «durmiendo/duermen» se aplican tanto a este sentido literal como al eufemístico, mostrando cuán naturalmente la metáfora surge de la realidad física. Los guardias de la tumba de Jesús afirman que los discípulos robaron el cuerpo mientras ellos dormían (Mt 28:13); Pedro duerme entre dos soldados en prisión (Hch 12:6).');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (70864, 'spa', 'Sueño o descanso', 'Se refiere al reposo o sueño, particularmente como eufemismo de la muerte. El uso que Jesús hace del lenguaje del ''sueño'' para referirse a la muerte de Lázaro suaviza la realidad, presentando la muerte como un descanso temporal, y anticipa el milagro de un sueño del cual se puede despertar, aunque la confusión de los discípulos muestra cómo la metáfora puede oscurecer el sentido literal hasta que llega la explicación.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (70865, 'spa', 'Común (compartido o ritualmente impuro/profano)', 'Común (compartido o ritualmente impuro/profano). Compartido, comunal, perteneciente a todos por igual. Se usa de la fe común que une a los creyentes (Tit 1:4; Jud 1:3) y del reparto radical de bienes en la comunidad primitiva de Jerusalén, donde ''todas las cosas eran comunes'' (Hch 2:44; 4:32). Refleja la idea griega de raíz de lo que se posee colectivamente en lugar de privadamente.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (70872, 'spa', 'Contaminar, hacer ritualmente impuro', 'Contaminar, hacer ritualmente impuro. El sentido activo dominante en el discurso de Jesús sobre la pureza. Lo que entra por la boca no contamina (κοινοῖ) a la persona, sino lo que sale del corazón (Mt 15:11, 18, 20; Mc 7:15, 18, 20, 23). La enseñanza redefine radicalmente la contaminación, trasladándola del contacto externo a la condición moral interior.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (70874, 'spa', 'Declarar profano, llamar común', 'Declarar profano, llamar común. Tratar como ritualmente inaceptable lo que Dios en realidad ha purificado. En la visión de Pedro, una voz celestial ordena: ''Lo que Dios ha limpiado, no lo llames común'' (Hch 10:15; 11:9). No se trata de contaminación real, sino del juicio humano que etiqueta algo como impuro, distinción con enormes implicaciones para la inclusión de los gentiles.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (70876, 'spa', 'Estar contaminado (pasivo)', 'Estar contaminado (pasivo). El estado resultante de haber sido hecho ritualmente impuro. En Hebreos 9:13, la sangre de machos cabríos y toros y las cenizas de una becerra santifican a ''los contaminados'' (κεκοινωμένους) para la purificación de la carne, señalando un estado de impureza ya existente.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (70879, 'spa', 'Compartir, participar, comulgar', 'Compartir o participar en algo con otra persona, abarcando tanto la contribución activa (dar de los propios recursos, como en Ro 12:13 y Gá 6:6) como la participación receptiva (tomar parte en bendiciones, sufrimientos o incluso pecados, como en 1 Ti 5:22 y He 2:14). El alemán ''teilhaben'' (''tener parte'') y el español ''compartir'' iluminan conjuntamente las dos facetas direccionales del término.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (70887, 'spa', 'Comunión, compañerismo, participación', 'Comunión, compañerismo, participación: Participación compartida y asociación en un vínculo espiritual o práctico. Teológicamente central en el lenguaje eucarístico de Pablo — la copa es una κοινωνία de la sangre de Cristo, el pan de su cuerpo (1 Co 10:16). Nombrada como práctica fundacional de la iglesia primitiva (Hch 2:42). Se extiende a la comunión vertical con Dios y su Hijo (1 Jn 1:3, 6-7; 1 Co 1:9) y a la participación material concreta, como la colecta para los santos.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (70891, 'spa', 'Generosidad participativa', 'Este adjetivo aparece únicamente en la carta pastoral de Pablo, describiendo a creyentes adinerados que deben estar ''dispuestos a compartir'' sus recursos. La evidencia multilingüe apunta consistentemente a la generosidad y la voluntad de distribuir las posesiones. La raíz griega vinculada a κοινωνία sugiere que el verdadero compartir crea comunidad, no mera caridad unidireccional.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (70892, 'spa', 'Partícipe, participante — aquel que comparte o participa de una realidad, experi', 'Partícipe, participante — aquel que comparte o participa de una realidad, experiencia o condición espiritual común, enfatizando la cosa compartida más que la relación personal. Pablo lo emplea de manera contundente en 1 Corintios 10:18-20 para advertir que comer de los sacrificios crea una participación genuina: quienes están junto al altar son ''partícipes'' del altar, y los que festejan ante los ídolos se convierten en ''partícipes'' con los demonios. Pedro, de modo similar, se llama a sí mismo partícipe de la gloria venidera.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (70893, 'spa', 'Socio, compañero — un asociado o compañero en una empresa o relación compartida,', 'Socio, compañero — un asociado o compañero en una empresa o relación compartida, enfatizando el vínculo interpersonal más que la participación abstracta. Santiago y Juan son llamados ''compañeros'' de pesca con Simón (Lc 5:10), Pablo elogia a Tito como su ''compañero'' de ministerio (2 Co 8:23), y a Filemón se le trata como ''compañero'' personal en la fe (Flm 1:17). Los fariseos niegan ser ''cómplices'' de sus antepasados que mataron a los profetas.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (70898, 'spa', 'Lecho, cama', 'Cama o diván para dormir o descansar, y por extensión el lecho conyugal como metonimia de las relaciones sexuales. En Lucas 11:7 es un lugar literal de descanso compartido con los hijos. En Romanos 9:10, Rebeca ''tuvo lecho'' (concibió) con Isaac — aquí κοίτη funciona como eufemismo digno para la relación marital. Hebreos 13:4 declara el lecho conyugal ''sin mancilla'', mientras que Romanos 13:13 usa el plural para la promiscuidad sexual.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (70899, 'spa', 'Dormitorio real', 'Lucas emplea este término para referirse al aposento real en el palacio de Herodes, donde Blasto ejercía como camarero, cargo equivalente al latín cubicularius. Esta posición implicaba acceso íntimo a las dependencias privadas del rey, lo que convertía a Blasto en un intermediario valioso para la delegación de Tiro. Las traducciones en múltiples idiomas coinciden en señalar un dormitorio privado.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (70900, 'spa', 'Escarlata', 'De color escarlata o carmesí, describiendo un rojo intenso producido con tinte de quermes. En el NT este color aparece cargado de simbolismo: el manto de burla puesto sobre Jesús por los soldados (Matt 27:28) evoca una realeza falsa, la lana escarlata de Heb 9:19 recuerda el rito de purificación con sus connotaciones de sangre y limpieza, y las vestiduras y la bestia escarlata de Apocalipsis (Rev 17:3-4; 18:12, 16) significan lujo, poder y corrupción.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (70902, 'spa', 'Semilla, grano', 'Una semilla o grano pequeño de una planta, la unidad reproductiva básica. Las siete apariciones neotestamentarias emplean κόκκος como vehículo de parábolas agrícolas y dichos sobre la fe. En Mateo 13:31 y Marcos 4:31 es una semilla de mostaza que ilustra el crecimiento del reino desde orígenes humildes; en Mateo 17:20 y Lucas 17:6 mide la cantidad asombrosamente pequeña de fe genuina capaz de lograr lo imposible.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (70905, 'spa', 'Adulación manipuladora', 'En la defensa que Pablo hace de sus propios motivos, contrasta la proclamación genuina del evangelio con «palabras de adulación», es decir, un discurso calculado para complacer a los oyentes en beneficio propio. El trasfondo clásico incluye amplia crítica filosófica contra los aduladores que socavan la virtud. Todos los testimonios lingüísticos subrayan la naturaleza engañosa e interesada de tal discurso frente a la comunicación honesta.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (70907, 'spa', 'Golpear con puños', 'Dar puñetazos o golpear con el puño, en sentido literal o figurado. Los relatos de la Pasión (Mt 26:67; Mc 14:65) lo emplean para describir a los guardias golpeando a Jesús después de su juicio. Pablo extiende la imagen al sufrimiento apostólico en 1Co 4:11 y, de forma inolvidable, a su «aguijón en la carne» en 2Co 12:7, donde un mensajero de Satanás lo «abofetea» espiritualmente.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (70908, 'spa', 'Juntarse con alguien', 'Juntarse con alguien. Vincularse o asociarse con una persona o grupo, formando un lazo social o relacional. Es el uso más frecuente en el Nuevo Testamento: el pródigo ''se juntó'' (ἐκολλήθη) a un ciudadano de aquel país (Lc 15:15), y Saulo intentó ''juntarse'' con los discípulos en Jerusalén (Hch 9:26).');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (70913, 'spa', 'Adherirse con devoción', 'Adherirse con devoción. Aferrarse devotamente a un bien moral abstracto. En Romanos 12:9, Pablo exhorta a los creyentes a estar ''adhiriéndoos a lo bueno'' (κολλώμενοι τῷ ἀγαθῷ). No se trata de una preferencia casual, sino de un compromiso tenaz y adhesivo, preservando la metáfora del pegamento.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (70914, 'spa', 'Unirse en matrimonio', 'Unirse en matrimonio. Unirse en el vínculo matrimonial, haciéndose eco de la ordenanza de la creación en Génesis. En Mateo 19:5 Jesús cita Génesis 2:24: el hombre ''se unirá'' (κολληθήσεται) a su mujer, subrayando la adhesión permanente y pactual que el matrimonio implica.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (70915, 'spa', 'Pegarse físicamente', 'Pegarse físicamente. Adherirse físicamente a una superficie, como el polvo que se pega a las sandalias. En Lucas 10:11 se dice a los setenta y dos que sacudan ''el polvo que se ha pegado'' (κολληθέντα) a sus pies, conectando directamente con la raíz etimológica del verbo en κόλλα, el pegamento físico.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (70918, 'spa', 'Amontonarse o acumularse', 'Amontonarse o acumularse. Acumularse o amontonarse, usado metafóricamente de pecados que se apilan unos sobre otros hasta alcanzar el cielo. En Apocalipsis 18:5, los pecados de Babilonia ''se han amontonado'' (ἐκολλήθησαν) hasta el cielo, apartándose del vínculo interpersonal hacia la imagen de objetos que se adhieren unos a otros en una masa creciente.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (70919, 'spa', 'Colirio medicinal', 'La visión apocalíptica de Juan emplea este término médico metafóricamente para referirse a la percepción espiritual. El contexto histórico es relevante: Laodicea era famosa por su polvo oftálmico frigio. El Cristo resucitado prescribe a la iglesia espiritualmente ciega que busque una sanación que sus célebres médicos no podían ofrecer, transformando un remedio físico conocido en símbolo de iluminación espiritual.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (70920, 'spa', 'Cambista de moneda', 'Cambista, persona que intercambia moneda por una comisión. Las tres apariciones en los Evangelios describen a Jesús volcando las mesas de los cambistas en el templo (Mateo 21:12, Marcos 11:15, Juan 2:15). Aunque el cambio de moneda cumplía un propósito legítimo —los peregrinos necesitaban moneda tiria para el impuesto del templo—, la práctica se había vuelto abusiva y había transformado el Atrio de los Gentiles en un mercado.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (70921, 'spa', 'Acortar el tiempo', 'Reducir o abreviar la duración de un período de tiempo. Las cuatro apariciones neotestamentarias se encuentran en el Discurso del Olivete (Mt 24:22 dos veces; Mc 13:20 dos veces), donde Jesús declara que Dios ha acortado los días de gran tribulación para que los elegidos puedan sobrevivir. El sentido clásico de mutilación física está ausente; el uso es enteramente temporal.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (70922, 'spa', 'Ciudad de Colosas', 'La forma en dativo plural se dirige a «los santos y hermanos fieles en Cristo que están en Colosas». Pablo escribe a una congregación que no había visitado personalmente, combatiendo una herejía cristológica temprana. Los testimonios multilingües conservan el nombre griego con ligeras variaciones fonéticas según cada lengua. El posterior declive y destrucción de la ciudad hicieron que la tradición cristiana se centrara en la epístola más que en el lugar.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (70923, 'spa', 'Seno, regazo, pecho', 'La parte frontal del torso — seno, regazo o pecho — entendida como lugar de cercanía íntima, consuelo y amor protector. El «seno de Abraham» (Lucas 16:22-23) evoca descanso en el abrazo del patriarca; el Hijo «en el seno del Padre» (Juan 1:18) expresa la intimidad divina única. Los términos españoles «seno», «regazo» y «pecho» capturan conjuntamente la amplitud semántica de este vocablo.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (70925, 'spa', 'Bahía, ensenada', 'Una bahía o ensenada — una curva de la costa que forma un cuerpo de agua protegido. En Hechos 27:39 los marineros divisan «cierta bahía con playa» donde esperan varar la nave. Este sentido geográfico es una extensión metafórica natural: así como el seno es un pliegue del cuerpo que envuelve y cobija, la bahía es un pliegue de la costa.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (70926, 'spa', 'Nadar', 'En la escena culminante de Hechos 27, la capacidad de nadar divide a los 276 pasajeros entre quienes podían salvarse por sí mismos de inmediato y quienes necesitaban tablas y restos del barco. El uso clásico abarca también el buceo y la zambullida. Todos los testimonios lingüísticos traducen este verbo de manera directa como el acto físico de nadar, sin extensión metafórica en este contexto.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (70927, 'spa', 'Estanque o piscina', 'Estanque, piscina o depósito público de agua, generalmente una instalación construida para baño o recolección hídrica. En Jn 5:2, 4, 7 designa el estanque de Betesda donde los enfermos se congregaban esperando sanidad; en Jn 9:7, Jesús envía al ciego a lavarse en el estanque de Siloé. Las excavaciones arqueológicas han confirmado ambos como sustanciales depósitos tallados en piedra.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (70928, 'spa', 'Colonia romana', 'La cuidadosa anotación geográfica y política de Lucas señala el estatus colonial romano de Filipos, que configuró la cultura urbana que Pablo encontró. Como colonia, Filipos gozaba de inmunidad fiscal y autogobierno bajo la ley romana. Este estatus resulta crucial cuando Pablo invoca su propia ciudadanía romana en Hechos 16:37.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (70930, 'spa', 'Cabellera larga', 'En el argumento paulino sobre las distinciones de género en el culto, el cabello largo sirve como cobertura divinamente otorgada a la mujer, en contraste con la vergüenza de tener la cabeza rapada. El trasfondo clásico incluye asociaciones con la belleza, la juventud y la apariencia femenina apropiada. La lógica de Pablo transita de la dotación natural a la práctica cultural.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (70931, 'spa', 'Recibir, obtener — recibir algo que se debe o se ha prometido', 'Recibir, obtener — recibir algo que se debe o se ha prometido: una recompensa, una retribución o un compromiso cumplido. La voz media enfatiza el recuperar lo que a uno le pertenece. Pablo lo usa en 2 Co 5:10 y Col 3:25 para el ajuste final de cuentas ante Cristo, mientras que Heb 10:36 lo vincula a la perseverancia necesaria para ''recibir la promesa''. El español ''obteniendo'' y el alemán ''empfangen'' resaltan el carácter adquisitivo del término.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (70934, 'spa', 'Traer, llevar — llevar o transportar físicamente algo a una persona o lugar, el ', 'Traer, llevar — llevar o transportar físicamente algo a una persona o lugar, el sentido más antiguo en voz activa heredado del uso clásico. En Lucas 7:37 la mujer ''habiendo traído'' (κομίσασα) un frasco de alabastro transmite el transporte real de un objeto. El español ''trayendo'' preserva con claridad este matiz activo y físico, en contraste con el sentido pasivo-receptivo que predomina en el resto del NT.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (70940, 'spa', 'Mejoría física', 'La precisión cronológica de Juan vincula la palabra autoritativa de Jesús (''tu hijo vive'') con la mejoría médica observable. Los siervos usan este adverbio para describir el momento decisivo en que la crisis pasó. Aunque el griego clásico conecta este vocablo con la elegancia, el uso neotestamentario apunta directamente a una recuperación física.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (70942, 'spa', 'Polvo levantado', 'Polvo agitado o alzado del suelo formando una nube visible. La etimología compuesta (κόνις + ὄρνυμι, «polvo» + «agitar») señala polvo en movimiento, no sedimento asentado. Las cinco apariciones neotestamentarias involucran gestos simbólicos: sacudir el polvo de los pies como testimonio contra quienes rechazan el evangelio (Mt 10:14; Lc 9:5; Lc 10:11; Hch 13:51), o arrojar polvo al aire como expresión de furia (Hch 22:23).');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (70943, 'spa', 'Cesar o amainar', 'Cesar, detenerse o amainar, específicamente referido al viento y las tormentas. Las tres apariciones describen el viento cesando en presencia de Jesús: Marcos 4:39, tras reprender la tormenta con «¡Calla, enmudece!»; Mateo 14:32, cuando Jesús y Pedro subieron a la barca después de caminar sobre el agua; y Marcos 6:51, al unirse Jesús a los discípulos en la barca durante la tempestad. El cese inmediato revela su autoridad soberana sobre la creación.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (70944, 'spa', 'Duelo fúnebre ritual', 'El duelo de la iglesia primitiva por Esteban involucra prácticas funerarias tradicionales pese a las circunstancias violentas de su muerte. La ''gran lamentación'' señala tanto un dolor genuino como el honor debido al primer mártir. El trasfondo clásico incluye plañideras profesionales y gestos ritualizados de aflicción. Se trata de un lamento formal y público, no de tristeza silenciosa.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (70945, 'spa', 'Derrota militar violenta', 'El autor de Hebreos evoca el triunfo militar de Abraham sobre los reyes, preparando el escenario para el misterioso encuentro con Melquisedec. El término enfatiza la derrota violenta: los cuatro reyes y sus ejércitos fueron aplastados de manera decisiva. Esta victoria establece la autoridad regia de Abraham, haciendo aún más significativa su sumisión ante Melquisedec.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (70946, 'spa', 'Trabajar duro, realizar un esfuerzo extenuante en una labor fisica o ministerial', 'Trabajar duro, realizar un esfuerzo extenuante en una labor fisica o ministerial. En espanol, trabajar y habiendo trabajado senalan el trabajo activo, mientras que en frances travailler y en aleman muehen confirman el esfuerzo productivo. Los lirios que ''no trabajan'' (Mt. 6:28; Lc. 12:27) y la descripcion de Pablo del trabajo apostolico (Jn. 4:38; 1 Co. 15:10) anclan este sentido dominante en diecinueve ocurrencias.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (70953, 'spa', 'Fatigarse, quedar agotado o exhausto por un esfuerzo sostenido', 'Fatigarse, quedar agotado o exhausto por un esfuerzo sostenido. En espanol, cansado y me he fatigado distinguen este sentido del mero trabajo. Jesus, cansado de su viaje junto al pozo de Jacob (Jn. 4:6), y la gran invitacion a todos los que ''trabajan y estan cargados'' (Mt. 11:28) ejemplifican este sentido en cuatro ocurrencias.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (70965, 'spa', 'Trabajo, esfuerzo, labor', 'Trabajo, esfuerzo, labor: Esfuerzo físico o mental extenuante, labor productiva y empeño dedicado al trabajo o al ministerio. El español «trabajo/trabajos» y el francés «travail» derivan del latín palabras que significan esfuerzo y sufrimiento, conservando la connotación de κόπος de que el trabajo significativo tiene un costo. Pablo habla del «trabajo» de otros en el cual los discípulos entran (Jn 4:38) e insiste en que la labor «en el Señor» nunca es en vano (1 Co 15:58).');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (70967, 'spa', 'Molestia, fastidio, incomodidad', 'Molestia, fastidio, incomodidad: Problema, molestia o fastidio causado a alguien, que aparece típicamente en la frase fija κόπους παρέχειν («causar/dar molestia»). El español «molestia/molestias» distingue nítidamente este sentido del trabajo productivo, señalando una interrupción no deseada en vez de esfuerzo constructivo. Cuando los discípulos se quejan del costoso ungüento de la mujer, Jesús responde: «¿Por qué le causan molestia?» (Mt 26:10; Mr 14:6).');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (70971, 'spa', 'Lamentarse, golpearse el pecho', 'Llorar, lamentarse o golpearse el pecho en duelo — el sentido de lamento en voz media que predomina en el NT (6 de 8 apariciones). Refleja la práctica antigua de golpearse a sí mismo como expresión de dolor, atestiguada en todo el mundo mediterráneo. En Lc 8:52 la multitud «se lamentaba» por la hija de Jairo, y en Lc 23:27 las mujeres seguían a Jesús «lamentándose» camino al Gólgota.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (70972, 'spa', 'Cortar ramas', 'Cortar, talar o arrancar — el sentido físico en voz activa de separar ramas o follaje. Solo dos apariciones neotestamentarias conservan este significado original: Mt 21:8 y Mr 11:8, donde las multitudes «cortaban» ramas de los árboles para extenderlas ante Jesús durante la entrada triunfal. La evidencia multilingüe hace inconfundible la distinción: el español pasa de ''se lamentaban'' (duelo) a ''cortaban'' (acción física).');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (70977, 'spa', 'Cuervo como provisión divina', 'En la versión de Lucas sobre la enseñanza de Jesús acerca de la ansiedad, los cuervos aparecen como ejemplo de criaturas que reciben sustento divino sin trabajo agrícola. La elección es llamativa: en el Antiguo Testamento los cuervos son tanto los proveedores milagrosos de Elías como símbolos de desolación. Todos los testimonios lingüísticos identifican al ave específica: córvidos grandes, negros y carroñeros. La lógica de Jesús avanza de lo menor a lo mayor.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (70978, 'spa', 'Muchacha, niña', 'Una niña o doncella joven, usado como término familiar y ligeramente diminutivo para una niña o adolescente. Todas las apariciones neotestamentarias se encuentran en Marcos y Mateo: la hija de Jairo a quien Jesús resucita de entre los muertos (Mt 9:24-25; Mr 5:41-42) y la hija de Herodías que danza ante Herodes (Mt 14:11; Mr 6:22). El equivalente alemán ''Mädchen'' — también diminutivo de ''Magd'' — refleja la misma formación diminutiva del griego.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (70981, 'spa', 'Rebelde contra Moisés', 'La triple condenación de Judas —«el camino de Caín… el error de Balaam… la rebelión de Coré»— sitúa a los falsos maestros en la peor compañía bíblica. La historia de Coré advierte contra el rechazo de la autoridad espiritual legítima. Los testimonios multilingües transliteran el nombre hebreo con ligeras variaciones. El argumento de Judas es tipológico: la tierra tragó a Coré; la destrucción aguarda a los rebeldes modernos.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (70984, 'spa', 'Corinto', 'Nombre propio de la ciudad de Corinto, el próspero centro comercial griego en el istmo, donde Pablo fundó una iglesia durante su segundo viaje misionero (Hechos 18:1). Sus seis apariciones neotestamentarias se concentran en la narrativa del ministerio paulino y su correspondencia con los creyentes corintios (1 Corintios 1:2; 2 Corintios 1:1, 23; 2 Timoteo 4:20).');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (70986, 'spa', 'Cornelio', 'Cornelio — centurión romano de la Cohorte Itálica con base en Cesarea, el converso gentil paradigmático en Hechos. Lucas lo presenta como devoto y temeroso de Dios antes de su encuentro con Pedro (Hch 10:1-2, 22). La visión angélica que le ordena enviar a buscar a Pedro (Hch 10:3-8), la propia visión de Pedro en la azotea (10:9-16) y el dramático descenso del Espíritu Santo sobre la casa de Cornelio (10:44-48) constituyen juntos un punto de inflexión en la misión de la iglesia.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (70987, 'spa', 'Medida de grano', 'La parábola de Jesús emplea detalles comerciales realistas, incluyendo esta considerable unidad de medida de grano. Cien coros de trigo representaban un valor enorme, equivalente a la cosecha de una extensión significativa de tierra. Los testimonios multilingües transliteran el préstamo semítico o emplean un genérico «medidas». La reducción de veinte coros (de 100 a 80) representa una condonación sustancial de la deuda.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (70988, 'spa', 'Adornar, decorar — embellecer o engalanar, hacer que algo o alguien resulte atra', 'Adornar, decorar — embellecer o engalanar, hacer que algo o alguien resulte atractivo mediante decoración u ornamento. Los fariseos ''adornan'' los sepulcros de los profetas (Mt 23:29); el templo está ''adornado'' con piedras nobles (Lc 21:5). Pablo aconseja a las mujeres adornarse con modestia (1 Ti 2:9), y Tito 2:10 exhorta a los siervos a ''adornar'' la doctrina de Dios. Pedro recuerda cómo las santas mujeres de antaño ''se adornaban'' con un espíritu apacible y sereno.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (70989, 'spa', 'Poner en orden, preparar — arreglar, disponer o alistar de manera práctica, enfa', 'Poner en orden, preparar — arreglar, disponer o alistar de manera práctica, enfatizando la función más que la belleza. En Mt 25:7 las vírgenes ''arreglaron'' (ἐκόσμησαν) las mechas de sus lámparas, un acto práctico de mantenimiento. En Mt 12:44 y Lc 11:25 la casa barrida está ''puesta en orden'' (κεκοσμημένον), describiendo el aseo doméstico y no la ornamentación. El español ''arreglaron'' capta con claridad este registro utilitario.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (70998, 'spa', 'Potestades cósmicas malignas', 'En el pasaje culminante de Efesios sobre la armadura espiritual, Pablo identifica al verdadero enemigo: no carne y sangre, sino poderes cósmicos que han usurpado autoridad sobre la presente era de tinieblas. Las asociaciones imperiales y astrológicas del término en el uso pagano hacen llamativa la apropiación paulina: estos «gobernadores del mundo» son meramente enemigos vencidos. Los creyentes luchan contra poderes que aparentan una soberanía que Cristo ya les arrebató.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (70999, 'spa', 'mundo (orden creado)', 'El orden creado, la tierra habitada o el sistema de la sociedad humana y sus valores: la esfera en que se desarrolla la obra redentora de Dios. Todas las lenguas principales lo vierten con un término dominante: mundo (esp.), monde (fr.), Welt (al.). En la teología joánica abarca un espectro estratificado: objeto del amor de Dios (Jn 3:16), escenario que Jesús entra a salvar (Jn 12:47) y escenario de la misión apostólica.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (71004, 'spa', 'adorno, decoración', 'Adorno o decoración exterior del cuerpo: el sentido etimológico originario de κόσμος como «disposición» u «orden bello». Se encuentra solo en 1 P 3:3, donde Pedro contrasta el κόσμος externo (trenzas, joyas de oro, vestidos finos) con la persona interior del corazón. El español lo traduce como adorno, distinguiéndolo claramente de mundo.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (71005, 'spa', 'Cristiano corintio', 'Entre los saludos finales desde Corinto, Cuarto recibe el cálido título de «el hermano», ya sea indicando su renombre o el afecto de Pablo. Su nombre latino sugiere conexiones romanas, ya fuera liberto o ciudadano. Los testimonios multilingües transliteran con variaciones fonéticas. Como muchos en los saludos finales paulinos, Cuarto encarna a los numerosos cristianos fieles cuyo servicio no dejó otro registro que esta mención.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (71006, 'spa', 'Imperativo arameo transliterado', 'El Evangelio de Marcos preserva ocasionalmente las palabras arameas de Jesús, transliterando aquí el imperativo ''levántate'' antes de traducirlo al griego. Los sonidos mismos que Jesús pronunció (''talitha koum'') se transmiten, aportando vivacidad de testigo presencial. Todos los testimonios lingüísticos transliteran en lugar de traducir, reconociendo que se trata de habla aramea preservada. El poder del mandato no reside en una fórmula elaborada, sino en la autoridad divina de quien lo pronuncia.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (71007, 'spa', 'Guardia militar', 'Destacamento militar romano o guardia de vigilancia. Las tres apariciones en Mateo 27:65–28:11 se refieren a la guardia apostada en la tumba de Jesús. Pilato dice a los líderes judíos «Ahí tenéis una guardia; id, aseguradlo como sabéis» (27:65). Sellan la tumba y colocan la guardia (27:66). Tras la resurrección, algunos soldados informan a los sumos sacerdotes (28:11), quienes los sobornan para difundir una versión falsa.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (71008, 'spa', 'Aligerar la nave', 'En el clímax de la tormenta, la tripulación toma medidas cada vez más desesperadas para mantener a flote la nave. El tiempo imperfecto sugiere una acción continua o repetida: iban aligerando el barco progresivamente. Habiendo ya arrojado por la borda la carga y el equipo (vv. 18-19), ahora sacrifican el valioso cargamento de trigo. Este fue el último recurso antes de encallar, mostrando la gravedad extrema de la crisis.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (71009, 'spa', 'Canasta de mimbre', 'Canasta rígida de mimbre de tamaño moderado, asociada en la literatura antigua al uso judío y en el NT exclusivamente a las doce canastas de fragmentos sobrantes de la alimentación de los cinco mil (Mateo 14:20; Marcos 6:43; Lucas 9:17; Juan 6:13). Los Evangelios contrastan intencionalmente κόφινος con la σπυρίς más grande usada en la alimentación de los cuatro mil, y Jesús mismo resalta esta distinción (Mateo 16:9-10).');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (71010, 'spa', 'Camilla, catre, lecho — una estera portátil para dormir o camilla sencilla usada', 'Camilla, catre, lecho — una estera portátil para dormir o camilla sencilla usada por los pobres y los enfermos, que aparece con frecuencia como el objeto cargado por la persona sanada como prueba visible de su restauración. El paralítico de Capernaúm se levanta y carga su camilla (Mc 2:4, 9, 11-12), al inválido de Betesda se le dice ''toma tu camilla y anda'' (Jn 5:8-11), y Eneas en Lida se levanta de su lecho tras ocho años de parálisis (Hch 9:33).');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (71015, 'spa', 'clamar por angustia', 'Gritar con fuerza por angustia, temor, dolor o necesidad urgente. Es el sentido dominante (41 veces), que transmite intensidad emocional cruda. Se ve en la súplica desesperada de la mujer cananea (Mt 15:22), Pedro hundiéndose en las olas (Mt 14:30) y el reconocimiento aterrorizado de Jesús por los endemoniados (Mt 8:29). El grito es típicamente involuntario, arrancado por la circunstancia.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (71021, 'spa', 'clamar en proclamación', 'Gritar en proclamación pública, apelación o invocación: un grito que anuncia en vez de suplicar. Aunque usa el mismo registro vocal intenso, el propósito pasa de la angustia personal a la declaración pública. Juan el Bautista ''clama'' su mensaje (Jn 1:15), la multitud grita ''¡Hosanna!'' (Mr 11:9) y Pablo grita estratégicamente sobre la resurrección ante el Sanedrín (Hch 23:6).');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (71039, 'spa', 'Resaca y disipación', 'Dolor de cabeza por borrachera, resaca; la embriaguez o el estupor físico y mental resultante del consumo excesivo de alcohol. En Lucas 21:34, Jesús advierte que los corazones pueden ''cargarse'' (βαρηθῶσιν) con κραιπάλῃ, la niebla y el peso de la disipación que embota la vigilancia espiritual. Emparejado con μέθῃ (borrachera) y las ansiedades mundanas, describe un estilo de vida de autoindulgencia que deja a la persona desprevenida ante la venida del Señor.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (71040, 'spa', 'Cráneo, calavera', 'El cráneo, la estructura ósea que protege el cerebro. Todas las apariciones neotestamentarias (Mt 27:33; Mc 15:22; Lc 23:33; Jn 19:17) emplean el término como parte del topónimo «lugar de la Calavera» (τόπος κρανίου), identificando el sitio de la crucifixión de Jesús. El vocablo traduce el arameo Gólgota y se latinizó como Calvaria, origen del español «Calvario».');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (71041, 'spa', 'Borde o franja ritual', 'El borde, orla o fleco-borla de una vestidura, en especial las borlas rituales (tzitzit) prescritas por la Torá. En Mt 9:20 y Lc 8:44, la mujer con hemorragia toca el κράσπεδον del manto de Jesús, creyendo que la sanará, lo que sugiere que las franjas portaban santidad simbólica. Mt 14:36 y Mr 6:56 describen multitudes suplicando tocar siquiera este borde. Mt 23:5 critica a los fariseos por alargar sus flecos ostentosamente.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (71042, 'spa', 'Poderoso, fuerte', 'Pedro emplea la clásica frase bíblica ''la poderosa mano de Dios'', cargada de resonancias del Éxodo. El adjetivo enfatiza poder y fuerza bruta: esta es la mano que venció a Faraón y juzga a las naciones. Sin embargo, el consejo paradójico de Pedro es humillarse bajo este poder en lugar de resistirlo. La mano es poderosa pero finalmente protectora para quienes se someten a ella en fe y obediencia.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (71043, 'spa', 'Fortalecerse o vigorizar', 'Crecer en fortaleza, ser robustecido o recibir poder, ya sea física o espiritualmente. En Lc 1:80 y 2:40 describe la maduración física y espiritual de Juan el Bautista y del niño Jesús respectivamente: ambos «crecían y se fortalecían». En 1 Co 16:13, Pablo ordena a los creyentes «sed fuertes» (imperativo), y en Ef 3:16 ora por el fortalecimiento interior mediante el Espíritu.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (71044, 'spa', 'Tomar fisicamente de la mano o asir a alguien, especialmente en el contexto comp', 'Tomar fisicamente de la mano o asir a alguien, especialmente en el contexto compasivo de la sanacion. Jesus ''toma de la mano'' a la suegra de Pedro (Mr 1:31), ''agarra la mano'' de la hija de Jairo (Mr 5:41) y ''toma'' a un muchacho con espiritu inmundo (Mr 9:27). El vocabulario selecciona contacto suave y de apoyo.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (71045, 'spa', 'Aprehender o arrestar a una persona con intencion hostil o por la fuerza', 'Aprehender o arrestar a una persona con intencion hostil o por la fuerza. Herodes ''prendio'' a Juan el Bautista (Mt 14:3); los principales sacerdotes querian ''prender'' a Jesus pero temian a la multitud (Mt 21:46); los siervos ''agarraron'' a los invitados en la parabola (Mt 22:6). Es el sentido dominante en los Evangelios con 21 apariciones.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (71048, 'spa', 'Retener firmemente ensenanzas, tradiciones, convicciones o realidades espiritual', 'Retener firmemente ensenanzas, tradiciones, convicciones o realidades espirituales. En Marcos 7:3, 8 los fariseos ''retienen'' la tradicion de los ancianos; Pablo exhorta a ''retener'' las tradiciones recibidas (2 Ts 2:15); Colosenses 2:19 advierte contra quienes no se ''asen'' de Cristo, la Cabeza. El agarre aqui es intelectual y espiritual.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (71052, 'spa', 'Obtener o asegurar un proposito u objetivo', 'Obtener o asegurar un proposito u objetivo. Uso singular en Hechos 27:13, donde sopla un viento suave del sur y los marineros suponen haberse ''apoderado'' de su proposito. Extiende la metafora del agarre fisico al ambito de lograr una meta, en un contexto nautico especializado.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (71055, 'spa', 'Ser retenido, impedido o restringido en voz pasiva', 'Ser retenido, impedido o restringido en voz pasiva. En Lucas 24:16, los ojos de los discipulos de Emaus ''estaban impedidos'' para reconocer a Jesus; en Hechos 2:24 era imposible que la muerte ''retuviera'' a Cristo; en Juan 20:23 los pecados ''son retenidos''. Abarca restricciones tanto fisicas como juridicas.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (71076, 'spa', 'Guardar, observar o custodiar tradiciones y costumbres con cuidado', 'Guardar, observar o custodiar tradiciones y costumbres con cuidado. En Marcos 7:4 los fariseos ''observan'' muchas tradiciones como lavar copas y jarros; en Marcos 9:10 los discipulos ''guardaron'' el asunto entre ellos. El enfasis recae en la observancia cuidadosa, distinto de la adhesion combativa del sentido 2.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (71078, 'spa', 'Título honorífico superlativo', 'Adjetivo superlativo que significa «excelentísimo» o «nobilísimo», usado en el NT exclusivamente como título formal de tratamiento para personas de alto rango. Lucas lo emplea para Teófilo (Lc 1:3), sugiriendo que el dedicatario tenía posición social o política. Pablo lo utiliza ante gobernadores romanos: Lisias escribe al «excelentísimo Félix» (Hch 23:26) y Pablo se dirige a Félix (Hch 24:3) y a Festo (Hch 26:25) con este mismo tratamiento.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (71080, 'spa', 'Poder, dominio, potencia', 'Poder, dominio, potencia. Poder soberano, fuerza suprema gobernante o dominio absoluto, usado predominantemente en contextos doxológicos y teológicos para atribuir fuerza incomparable a Dios o a Cristo. Aparece en fórmulas litúrgicas de alabanza (1 P 4:11, ''a él sea la gloria y el κράτος''; Ap 5:13, ''el poder y la potencia por siempre''). También describe la acción divina — Dios realizando κράτος con su brazo (Lc 1:51).');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (71085, 'spa', 'Gritar, clamar fuerte', 'Gritar fuertemente, clamar o vociferar con urgencia o vehemencia. κραυγάζω es una forma intensificada de κράζω que transmite una expresión vocal poderosa y a menudo cargada de emoción. Su rango neotestamentario incluye el grito hostil de la multitud — la exigencia de crucificar a Jesús (Jn 19:6, 15; Hch 22:23) — así como la aclamación gozosa en la entrada triunfal (Jn 12:13) y el grito autoritativo de Jesús al llamar a Lázaro del sepulcro (Jn 11:43).');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (71091, 'spa', 'Clamor, grito', 'Exclamación vocal intensa que expresa emoción fuerte, ya sea gozo, urgencia, dolor o contienda. El espectro semántico neotestamentario va desde el gozoso clamor nocturno del heraldo del esposo (Mateo 25:6) y el grito jubiloso de Elisabet (Lucas 1:42), hasta el vocerío airado del Sanedrín (Hechos 23:9) y los gritos angustiados de Cristo en oración (Hebreos 5:7). Pablo cataloga κραυγή junto con la amargura y la ira como vicios a desechar (Efesios 4:31).');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (71097, 'spa', 'Mejor o superior', 'Mejor, más excelente, superior en calidad o conveniencia. Las cuatro ocurrencias neotestamentarias emplean esta palabra para comparar dos estados o resultados y declarar uno preferible. En Fil 1:23, Pablo sopesa vivir frente a partir para estar con Cristo, calificando lo segundo como κρεῖσσον; en Heb 6:9 el autor asegura a los creyentes «cosas mejores» que acompañan a la salvación.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (71098, 'spa', 'Mejor, superior, más excelente', 'Mejor, superior, más excelente. Superior en calidad, valor o condición moral; mejor o más excelente que otra cosa. Hebreos despliega esta palabra repetidamente para demostrar la superioridad de Cristo sobre los ángeles (Heb 1:4), el sacerdocio levítico (Heb 7:7, 19), el antiguo pacto (Heb 7:22) y los sacrificios terrenales (Heb 9:23).');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (71101, 'spa', 'Colgar, crucificar', 'Colgar o suspender a alguien o algo físicamente, especialmente en el contexto de la crucifixión o ejecución en un madero (ξύλον). La predicación apostólica en Hechos emplea este verbo repetidamente para la muerte de Cristo: ''a quien ustedes mataron colgándolo en un madero'' (Hch 5:30; 10:39). Lucas 23:39 lo aplica a los criminales crucificados junto a Jesús.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (71102, 'spa', 'Depender de', 'Uso figurado que significa depender de, descansar sobre o estar supeditado a algo. En Mateo 22:40, Jesús declara que toda la Ley y los Profetas κρέμαται (''cuelga'') de los dos mandamientos del amor. La metáfora traslada la imagen física de suspensión al ámbito de la dependencia lógica o moral: todo pende de, y por tanto se fundamenta en, el amor a Dios y al prójimo.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (71107, 'spa', 'Barranco escarpado', 'Un barranco empinado, acantilado o precipicio. Los tres Evangelios Sinópticos usan esta palabra en los relatos paralelos del endemoniado gadareno: cuando Jesús permite que los demonios entren en una piara de cerdos, los animales se precipitan por el barranco hacia el mar y se ahogan (Mateo 8:32, Marcos 5:13, Lucas 8:33). La geografía es realista, pues la costa oriental del mar de Galilea presenta acantilados pronunciados que descienden hasta el agua.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (71109, 'spa', 'Compañero de Pablo', 'Entre los compañeros de Pablo mencionados en su última epístola, Crescente aparece como alguien que partió para el ministerio, ya sea a Galacia o posiblemente a la Galia, según la variante manuscrita. Su nombre latino sugiere un trasfondo romano. A diferencia de Demas el desertor, Crescente parece haberse marchado con la bendición de Pablo para un servicio legítimo, representando a los colaboradores fieles que continuaron la obra misionera.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (71110, 'spa', 'Isla de Creta', 'La isla de Creta en el mar Mediterráneo, lugar significativo en el ministerio paulino. En Hch 27:7-21, Creta es el escenario de una decisión crítica durante el viaje de Pablo a Roma: el barco lucha por rodear el cabo Salmón, se refugia brevemente en Buenos Puertos y parte desastrosamente pese a la advertencia de Pablo, lo que desemboca en el naufragio. En Tito 1:5, Pablo recuerda haber dejado a Tito en la isla para completar la organización eclesial.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (71111, 'spa', 'Cebada como grano', 'La visión apocalíptica de Juan sobre el jinete del caballo negro (hambruna) incluye precios específicos de cereales que señalan una angustia económica severa. La cebada, el grano de la pobreza, cuesta un tercio del precio del trigo pero aún requiere el salario diario por tres litros, apenas suficiente para sobrevivir. La construcción genitiva indica ''de cebada'' modificando ''litros''.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (71113, 'spa', 'El sentido dominante abarca la decision judicial, el veredicto y la condenacion,', 'El sentido dominante abarca la decision judicial, el veredicto y la condenacion, es decir, el resultado del juicio divino o humano. Jesus advierte de una mayor condenacion para los escribas que devoran las casas de las viudas (Mr. 12:40; Mt. 23:14). Pablo ensena que el juicio divino cae justamente sobre los pecadores (Ro. 2:2-3; 3:8) y que participar indignamente de la Cena del Senor acarrea juicio sobre uno mismo (1 Co. 11:29).');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (71117, 'spa', 'Un uso distintivo en 1 Corintios 6', 'Un uso distintivo en 1 Corintios 6:7 donde krima significa un pleito o disputa legal entre creyentes. Pablo pregunta: ''?Por que no mas bien ser agraviados?'' — reprendiendo a los cristianos por llevar sus pleitos (krimata) ante tribunales paganos. El espanol pleitos captura este sentido con precision, distinguiendolo del peso teologico de la condenacion divina.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (71121, 'spa', 'juzgar, emitir juicio', 'El sentido judicial activo: juzgar, evaluar, emitir juicio o condenar. Es el uso dominante, que abarca la enseñanza de Jesús sobre el juicio mutuo (Mt 7:1; Lc 6:37), la autoridad escatológica de juzgar a las doce tribus (Mt 19:28) y el juicio justo de Dios (Jn 5:22; Ro 2:16). El español juzgar capta con precisión este núcleo forense.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (71130, 'spa', 'ser juzgado, comparecer', 'El sentido pasivo y medio: ser juzgado, comparecer ante un tribunal, quedar bajo juicio. En Jn 3:18 el creyente «no es juzgado» mientras que el incrédulo «ya ha sido juzgado». En Hch 23:6 Pablo declara «soy juzgado respecto a la esperanza de la resurrección». La pasiva conlleva frecuentemente peso escatológico (Mt 7:1-2; Ro 3:7).');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (71144, 'spa', 'decidir, determinar', 'El sentido deliberativo: decidir, determinar, resolver un curso de acción. Hch 20:16 registra que Pablo «decidió» pasar navegando junto a Éfeso; Hch 16:4 describe a los apóstoles entregando «decisiones» tomadas en Jerusalén; Hch 25:25 lo usa para la determinación judicial de Festo. El sentido pasa de la sala del tribunal a la cámara del consejo.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (71176, 'spa', 'demandar, pleitear', 'El sentido litigioso: interponer una demanda, pleitear ante la ley. En Mt 5:40, Jesús dice: «al que quiera demandarte (κρίνω) y quitarte la túnica, déjale también la capa». El español demandar aísla esta acción legal iniciadora, distinta del veredicto de un juez, como sentido propio.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (71180, 'spa', 'juicio, condenación', 'El acto, proceso o resultado de emitir un veredicto judicial, que abarca el juicio escatológico divino (Mt 10:15 ''día del juicio''; Mt 12:36 ''toda palabra ociosa''), la autoridad para juzgar delegada a Cristo (Jn 5:22, 27 ''el Padre ha dado todo el juicio al Hijo'') y el sentido ético de justicia como obligación moral (Mt 23:23 ''la justicia, la misericordia y la fe''). También denota la condenación como sentencia resultante del proceso judicial.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (71187, 'spa', 'Tribunal judicial', 'Tribunales o juzgados donde se resuelven causas legales. Pablo usa esta palabra en 1 Corintios 6:2, 4 para cuestionar a los creyentes que llevan sus disputas ante tribunales seculares: «¿No sabéis que los santos han de juzgar al mundo? Y si el mundo ha de ser juzgado por vosotros, ¿sois acaso indignos de juzgar asuntos menores?». Santiago 2:6 describe cómo los ricos arrastran a los pobres ante los tribunales, ilustrando la explotación económica.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (71188, 'spa', 'Juez (el que juzga o decide)', 'Juez (el que juzga o decide): Quien juzga, decide casos o emite veredictos con autoridad. Aplicado a magistrados y árbitros humanos en procedimientos legales (Mt 5:25; Lc 12:58; Hch 24:10), a los jueces-libertadores premonárquicos de Israel (Hch 13:20) y de manera suprema a Dios como Juez cósmico de todos (He 12:23; Stg 4:12; 2 Ti 4:8). El español capitaliza «Juez» al referirse a Dios y usa minúscula para los jueces humanos, revelando la misma distinción teológica inherente al término griego.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (71191, 'spa', 'Discernidor espiritual', 'El autor de Hebreos personifica la Escritura como un agente activo que juzga los pensamientos humanos: la palabra misma es κριτικός, capaz de criticar y discernir. El trasfondo clásico incluye gramáticos y eruditos que ejercían juicio crítico sobre textos; aquí los roles se invierten, y el texto juzga al lector. La palabra penetra hasta lo más profundo del corazón humano.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (71192, 'spa', 'Llamar a la puerta', 'Llamar o golpear a una puerta buscando que se abra. El griego κρούω (de una raíz que significa ''golpear'') se especializa en el NT para el acto de llamar a una puerta. La instrucción de Jesús «llamad y se os abrirá» (Mt 7:7-8; Lc 11:9-10) transforma este gesto en metáfora de la oración persistente y llena de fe. Lucas 12:36 lo emplea para siervos que esperan el regreso de su amo, y Hechos 12:13-16 ofrece una vívida escena literal.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (71198, 'spa', 'Lugar escondido', 'En la enseñanza de Jesús sobre la luz y la revelación, el ''lugar oculto'' representa la ubicación incorrecta para una lámpara: cualquier sitio escondido de la vista anula el propósito de la lámpara. El término puede significar cripta, bóveda o cuarto secreto. La lógica de Jesús es directa: las lámparas existen para iluminar, así que esconderlas resulta absurdo. Aplicado espiritualmente, advierte contra ocultar la verdad.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (71199, 'spa', 'Oculto, secreto', 'Oculto, secreto: Lo que está escondido, secreto o invisible — usado tanto como adjetivo como sustantivamente para referirse a realidades ocultas. Central en la enseñanza de Jesús sobre la piedad auténtica: limosna, oración y ayuno hechos «en secreto» ante el Padre que ve lo oculto (Mt 6:4, 6, 18). Pablo lo extiende a las cosas ocultas del corazón expuestas en el juicio divino (Ro 2:16; 1 Co 4:5; 14:25). Marcos 4:22 y Lucas 8:17 afirman que nada oculto quedará sin revelarse.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (71204, 'spa', 'Esconder, ocultar algo', 'Esconder, ocultar algo: Esconder u ocultar algo activa y deliberadamente — usos transitivos donde el sujeto intencionalmente oculta un objeto, persona o verdad de otros. Jesús agradece al Padre por haber «escondido» estas cosas de los sabios (Mt 11:25; Lc 10:21), un hombre esconde el tesoro que encontró (Mt 13:44, activo), el siervo temeroso «escondió» el talento de su amo en la tierra (Mt 25:18, 25), y una mujer «escondió» levadura en la harina (Lc 13:21).');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (71205, 'spa', 'Estar escondido, esconderse', 'Estar escondido, esconderse: Estar oculto, yacer escondido o esconderse — usos pasivos, estativos y medio-reflexivos donde el sujeto es quien se encuentra en estado de ocultamiento, no el agente que esconde. Una ciudad sobre un monte «no puede esconderse» (Mt 5:14), cosas «escondidas desde la fundación del mundo» se revelan en parábolas (Mt 13:35), un tesoro yace «escondido» en un campo (Mt 13:44, participio pasivo), y la verdad permanece oculta a la percepción humana (Lc 18:34).');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (71219, 'spa', 'Claridad cristalina', 'Juan emplea este verbo poco frecuente para describir la claridad sobrenatural de la Nueva Jerusalén: resplandece con transparencia cristalina. El término sugiere el proceso de volverse cristalino, alcanzando una translucidez perfecta. La ciudad no simplemente contiene cristal, sino que posee la cualidad intrínseca del cristal: pureza absoluta y luminosidad que refleja la gloria divina.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (71221, 'spa', 'Ocultamente, en secreto', 'La enseñanza ética de Pablo contrasta la vida abierta de la luz con las acciones ocultas en la oscuridad secreta. El adverbio subraya el ocultamiento: estos hechos suceden ''en secreto'' porque no sobreviven a la exposición. El uso clásico incluye conspiraciones y actividades clandestinas. La estrategia retórica de Pablo sugiere que ciertos pecados son tan vergonzosos que discutirlos en detalle resulta inapropiado.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (71222, 'spa', 'Adquirir, obtener', 'Procurar u obtener posesión de algo para uno mismo, abarcando propiedad material, derechos legales y cualidades abstractas. La voz media subraya la iniciativa personal: quien adquiere actúa en su propio interés. En Hechos 8:20, Pedro reprende a Simón el Mago por pensar que el don de Dios podría ''adquirirse'' con dinero, mientras que en Lucas 21:19 la perseverancia es el medio por el cual los creyentes ''ganan'' sus almas.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (71229, 'spa', 'Posesion o propiedad', 'Posesion, propiedad, hacienda. Se refiere a bienes materiales adquiridos, especialmente tierras o riqueza considerable. En los relatos sinopticos del joven rico (Mt 19:22; Mc 10:22), el plural κτήματα subraya la magnitud de sus posesiones que hacian costoso el discipulado. En Hch 2:45 y 5:1 designa bienes raices vendidos por los primeros creyentes para redistribucion comunitaria.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (71230, 'spa', 'Animal domestico o ganado', 'Animal domesticado, bestia de carga o ganado. Abarca desde animales de montura hasta el ganado en general. En Lc 10:34 y Hch 23:24 se refiere especificamente a cabalgaduras usadas para transporte. En 1 Co 15:39 Pablo lo usa en sentido biologico mas amplio, distinguiendo la carne de los κτήνη de la de humanos, aves y peces. Ap 18:13 lo incluye entre mercancias comerciales.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (71231, 'spa', 'Dueños de propiedades', 'En el resumen lucano de la vida comunitaria, los ''dueños'' de propiedades liquidaban voluntariamente sus bienes para sostener a los creyentes necesitados. El término emplea lenguaje jurídico directo: eran poseedores legítimos que ejercían su derecho de propiedad. Lo notable no es el vocablo sino la acción: propietarios que renunciaban a sus posesiones por amor al prójimo.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (71232, 'spa', 'Crear, dar existencia', 'Crear, dar existencia. Denota el acto divino de crear o dar existencia a algo, ya sea el cosmos físico (Mc 13:19), la humanidad (1 Co 11:9) o la nueva persona espiritual en Cristo (Ef 2:10; 4:24). Las formas pasivas (''habiendo sido creado'') enfatizan la dependencia de la criatura respecto al poder originador de Dios.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (71235, 'spa', 'Creador (sustantivado)', 'Creador (sustantivado). La forma participial usada como sustantivo para designar a Dios como ''el Creador'' o ''el que creó.'' En Mateo 19:4 Jesús apela a ''el que los hizo desde el principio,'' y en Romanos 1:25 Pablo traza la distinción fundamental entre Creador y criatura. Este uso funciona como un título divino que fundamenta la adoración en el acto originario de Dios.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (71242, 'spa', 'Creación, orden creado', 'Creación, orden creado: El acto de crear o la totalidad de lo que Dios ha hecho, abarcando tanto el evento abstracto («desde el principio de la creación», Mr 10:6; 13:19) como el resultado concreto: todo ser viviente. El español distingue consistentemente «creación» para el acto y «criatura» para el ser, una distinción que el inglés colapsa. El alemán «Schöpfung» capta la grandiosidad del acto creador divino.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (71244, 'spa', 'Institución, ordenanza', 'Institución, ordenanza: Una institución humana, estructura social u ordenanza — una extensión del crear divino al ordenamiento humano. Se encuentra solo en 1 Pedro 2:13, donde se exhorta a los creyentes a someterse a «toda institución humana» (πάσῃ ἀνθρωπίνῃ κτίσει). El español lo traduce como «institución», distinguiéndolo claramente del sentido de creación divina. La metáfora es poderosa: la gobernanza humana se enmarca como una fundación con propósito.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (71247, 'spa', 'Criatura de Dios', 'Cosa creada, criatura hecha por Dios. Se refiere a cualquier entidad que debe su existencia a la actividad creadora divina. En 1 Ti 4:4 Pablo afirma la bondad de toda κτίσμα, contrarrestando prohibiciones asceticas sobre alimentos. En Stg 1:18 se aplica a los creyentes como ''primicias'' de las criaturas de Dios. Ap 5:13 y 8:9 lo usan para la totalidad de la creacion viviente.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (71248, 'spa', 'Creador fiel', 'Pedro fundamenta el sufrimiento cristiano en la teología: los creyentes pueden ''encomendar sus almas'' a Dios porque es su fiel Creador. El término evoca el poder divino y su rol fundacional: quien hizo todas las cosas puede preservar a quienes creó a su imagen. La LXX lo aplica a la obra creadora cósmica de Dios.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (71249, 'spa', 'Astucia engañosa', 'La metáfora paulina recurre a la cultura del juego de dados: el término originalmente se refería a jugar con dados y luego al engaño y las trampas del juego antiguo. Los falsos maestros manipulan como tahúres deshonestos, empleando artimañas para engañar. Pablo desea que los creyentes maduren para reconocer la manipulación doctrinal.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (71250, 'spa', 'Gobierno y dirección', 'Pablo enumera las ''administraciones'' entre los dones que el Espíritu otorga a la iglesia. La metáfora náutica (timonear, pilotear) sugiere destreza y capacidad dada por Dios para navegar la iglesia a través de las dificultades. No es mera burocracia sino capacidad espiritual para discernir la dirección correcta y guiar a la comunidad de fe.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (71252, 'spa', 'En derredor', 'Alrededor, en derredor, en círculo por todos lados. Las tres apariciones se encuentran en Apocalipsis 4, describiendo la visión de Juan del trono de Dios: un arcoíris rodea el trono (4:3), veinticuatro tronos con ancianos se disponen a su alrededor (4:4), y cuatro seres vivientes se sitúan en torno al trono, cada uno cubierto de ojos por doquier (4:8). El uso reiterado crea una imagen vívida de círculos concéntricos de adoración.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (71253, 'spa', 'Rodear o asediar', 'Rodear, cercar o asediar formando un anillo alrededor de una persona, lugar o grupo. La raiz κύκλος (circulo) se percibe en cada uso. Lc 21:20 lo emplea profeticamente para ejercitos rodeando Jerusalen en asedio militar. Jn 10:24 lo aplica a los judios cerrando el cerco sobre Jesus en el portico de Salomon. Hch 14:20 describe a discipulos reunidos en circulo protector alrededor de Pablo.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (71254, 'spa', 'Alrededor / en círculo', 'Preposición y adverbio espacial que significa ''alrededor, en derredor, en círculo'', indicando una orientación de rodeo o circundante. Se usa cuando Jesús mira alrededor a los que están sentados junto a él (Mc 3:34), al recorrer las aldeas en derredor (Mc 6:6) y para el circuito misionero de Pablo desde Jerusalén hasta Ilírico (Ro 15:19). El español «alrededor» y el alemán «ringsumher» subrayan esa cualidad de abarcar por completo.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (71259, 'spa', 'Revolcadero de cieno', 'Pedro emplea una imagen repugnante para describir a los apóstatas: la cerda lavada que vuelve a revolcarse en el lodo. El término designa el revolcadero, el lodazal donde los cerdos se revuelcan. Se puede lavar a un cerdo, pero su naturaleza lo arrastra de vuelta a la inmundicia. Más que recaída, es retorno a la verdadera naturaleza.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (71260, 'spa', 'Revolcarse en convulsiones', 'La narrativa de Marcos capta el asalto del demonio sobre el muchacho: convulsiones, caída, rodar por el suelo, espuma. El imperfecto sugiere un revolcarse repetido y continuo. El verbo describe movimientos convulsivos fuera del control de la víctima. El español ''rodaba'' capta bien el movimiento giratorio involuntario previo a la liberación por Cristo.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (71261, 'spa', 'Lisiado o mutilado', 'Lisiado, mutilado de un miembro, deforme. Describe a una persona con una mano o pie inutilizado o amputado. En Mt 15:30-31 los κυλλοί figuran entre las multitudes afligidas traidas a Jesus para sanacion, junto a ciegos y cojos, cuya restauracion demuestra el poder mesianico. En Mt 18:8 y Mc 9:43 Jesus lo emplea en enseñanza radical sobre el discipulado.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (71262, 'spa', 'Ola o oleaje', 'Ola o oleaje del mar: la masa de agua encrespada impulsada por el viento o la tormenta. Las cinco apariciones neotestamentarias representan olas marinas literales o metaforicas. En los relatos sinopticos de la tempestad (Mt 8:24; Mc 4:37) transmite la fuerza natural abrumadora que amenaza una pequeña embarcacion. Judas 1:13 extiende la imagen al caos moral, retratando a los falsos maestros como ''fieras olas del mar''.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (71263, 'spa', 'Címbalo, instrumento percusivo', 'El capítulo del amor de Pablo usa el címbalo como imagen del habla sin amor: ruido metálico que no significa nada. Los címbalos eran comunes en la adoración del templo judío y en ritos paganos. No son intrínsecamente malos, pero producen mero ruido separados de su propósito musical. Sin amor, todo discurso queda reducido a estrépito vacío.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (71264, 'spa', 'Comino, especia menor', 'La crítica de Jesús al legalismo farisaico usa el comino como ejemplo de precisión desenfocada: calculaban diezmos sobre insignificantes semillas mientras descuidaban la justicia y la misericordia. Las semillas de comino eran diminutas y de escaso valor comparadas con el trigo o el aceite. El griego clásico incluía un proverbio sobre partir comino para describir la tacañería extrema.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (71265, 'spa', 'Perrito domestico', 'Perrito, perro pequeño de casa. Diminutivo que distingue a los perros domesticos pequeños de los perros callejeros grandes e impuros (κύνες) del antiguo Cercano Oriente. Las cuatro apariciones neotestamentarias pertenecen al mismo episodio: el dialogo de la mujer sirofenicia/cananea con Jesus (Mt 15:26-27; Mc 7:27-28). La forma diminutiva suaviza la metafora — son mascotas bajo la mesa familiar, no carroñeros de afuera.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (71266, 'spa', 'Chipriota', 'Un chipriota, alguien originario de Chipre. Bernabé es identificado como «levita, chipriota de nacimiento» en Hechos 4:36, lo que explica su trasfondo familiar en esta isla mediterránea con una considerable diáspora judía. Hechos 11:20 menciona a creyentes chipriotas (junto con cirenenses) que fueron a Antioquía y fueron pioneros en predicar a los griegos. Hechos 21:16 presenta a Mnasón, «chipriota, discípulo antiguo», quien brindó hospitalidad a Pablo.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (71267, 'spa', 'Isla de Chipre', 'Chipre — la gran isla griega en el Mediterraneo oriental, al sur de Asia Menor. En Hechos funciona como punto clave en la mision cristiana primitiva: creyentes dispersados por la persecucion llevaron el evangelio alli (Hch 11:19), Pablo y Bernabe lanzaron su primer viaje desde sus costas (Hch 13:4), y Bernabe regreso despues con Marcos (Hch 15:39).');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (71268, 'spa', 'Inclinarse, agacharse', 'Inclinarse, agacharse o doblarse hacia abajo. Juan el Bautista usa esta palabra en Marcos 1:7, declarándose indigno de «inclinarse para desatar» las correas de las sandalias del Mesías, tarea considerada demasiado humilde incluso para algunos esclavos. En Juan 8:6, 8, Jesús «se inclinó y escribió en el suelo» cuando los escribas y fariseos le trajeron a la mujer sorprendida en adulterio, creando una pausa dramática que desvía la atención de la acusación.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (71269, 'spa', 'Cirenense', 'Habitante u oriundo de Cirene, la ciudad colonial griega en el norte de África con una importante población judía de la diáspora. Simón de Cirene, requisado para cargar la cruz de Jesús (Mateo 27:32; Marcos 15:21; Lucas 23:26), es el cirenense más destacado del NT. Otros cirenenses figuran como miembros de la sinagoga de los Libertos que disputaban con Esteban (Hechos 6:9) y como evangelistas pioneros en Antioquía (Hechos 11:20; 13:1).');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (71274, 'spa', 'Cirene, ciudad norteafricana', 'Hechos menciona repetidamente a Cirene y los cireneos en la expansión de la iglesia primitiva. Esta ciudad griega norteafricana tenía una comunidad judía considerable con fuertes vínculos con Jerusalén. Cireneos en Pentecostés, Simón cargando la cruz y líderes cireneos en Antioquía resaltan la importancia de esta comunidad en la Diáspora.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (71275, 'spa', 'Cirenio, gobernador romano', 'Lucas proporciona anclaje histórico para el nacimiento de Jesús mediante la referencia a la gobernación de Cirenio y el censo. La forma en genitivo lo identifica como gobernador de Siria. Todos los idiomas transliteran el nombre latino (P. Sulpicius Quirinius) con variaciones fonéticas. El enigma de coordinar esta referencia con las fechas conocidas sigue siendo objeto de estudio.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (71278, 'spa', 'Ejercer señorío', 'Ser señor o amo de algo, ejercer autoridad gobernante o dominio sobre una persona, fuerza o ámbito. El verbo conlleva un tono de control soberano más que de orientación apacible. En Lucas 22:25 Jesús lo identifica con el estilo opresivo de los reyes gentiles, mientras Pablo lo reutiliza para describir poderes cósmicos: el dominio de la muerte cesó con la resurrección (Ro 6:9) y el dominio del pecado termina bajo la gracia (Ro 6:14).');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (71284, 'spa', 'Señor/título divino', 'El título divino usado para Dios el Padre y para Jesucristo, reconociendo su soberanía, autoridad suprema y naturaleza divina.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (71286, 'spa', 'amo/autoridad humana', 'Un amo o señor humano que ejerce autoridad sobre otros, como el dueño de esclavos o un gobernante.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (71297, 'spa', 'señor/cortesía', 'Un tratamiento respetuoso de cortesía dirigido a un hombre, equivalente a ''señor'' — sin implicar necesariamente autoridad o divinidad.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (71298, 'spa', 'dueño/propietario', 'El dueño o propietario de algo, quien tiene derechos sobre una posesión.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (71299, 'spa', 'Señorio y dominio', 'Señorio, dominio, autoridad gobernante; tambien una clase de potestades angelicales. Abarca tanto la cualidad abstracta de gobierno soberano como sus portadores personificados en la jerarquia celestial. En Ef 1:21 Cristo es exaltado sobre toda κυριότης, y en Col 1:16 las κυριότητες se enumeran entre los ordenes celestiales creados. En 2 Pe 2:10 y Jud 8, los falsos maestros desprecian esta autoridad establecida por Dios.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (71301, 'spa', 'Perro despreciado', 'Perro — literalmente un canino carroñero, pero en cada aparicion neotestamentaria con fuertes connotaciones de impureza ritual, desprecio moral o absoluta bajeza. En Mt 7:6 los perros representan a quienes son indignos de la verdad sagrada; en Fil 3:2 Pablo insulta a los oponentes judaizantes; en Lc 16:21 los perros subrayan la miseria de Lazaro. Ap 22:15 usa el termino para quienes quedan excluidos de la nueva Jerusalen.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (71302, 'spa', 'Miembros o cadáveres', 'El autor de Hebreos emplea este término para los cadáveres de la generación del desierto: sus «miembros» cayeron en el desierto sin alcanzar la Tierra Prometida. La palabra normalmente significa extremidades corporales, aquí usada colectivamente para cadáveres. El alemán «Glieder» conserva el sentido de miembros. La imagen evoca Números 14 y el juicio divino.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (71303, 'spa', 'Prohibir con autoridad, ordenar que algo no se haga', 'Prohibir con autoridad, ordenar que algo no se haga. Aunque el frances empecher y el espanol impedir se solapan con el sentido 1, los contextos revelan una prohibicion autoritativa: Jesus reprende a los discipulos que ''prohiben'' a los ninos acercarse (Mt. 19:14; Mr. 10:14), y surgen disputas sobre prohibir a alguien que expulsaba demonios (Mr. 9:38-39). Once ocurrencias llevan esta fuerza imperativa.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (71304, 'spa', 'Impedir, obstruir o restringir a alguien de proceder o actuar — prevencion pract', 'Impedir, obstruir o restringir a alguien de proceder o actuar — prevencion practica, no mandato autoritativo. El aleman hindert y el espanol fui impedido capturan este sentido de bloqueo. Pablo fue ''impedido'' de visitar Roma (Ro. 1:13), el eunuco etiope pregunta ''que impide que yo sea bautizado?'' (Hch. 8:36), y los fariseos ''impedian'' a los que entraban al reino (Lc. 11:52). Doce ocurrencias llevan este sentido.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (71320, 'spa', 'Un asentamiento rural sin murallas, mas pequeno y menos fortificado que una poli', 'Un asentamiento rural sin murallas, mas pequeno y menos fortificado que una polis (ciudad). Los Evangelios Sinopticos emplean este termino para describir los pueblos que Jesus visitaba durante su ministerio galileo (Mt. 9:35; Mr. 6:6, 36, 56). Las traducciones interlingueisticas lo rinden uniformemente como una pequena poblacion rural: espanol ''aldea'', frances ''village'', aleman ''Dorf''. El griego clasico contrastaba kome con polis para marcar el limite entre lo rural y lo urbano.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (71322, 'spa', 'Pueblos o aldeas grandes', 'La estrategia galileana de Jesús consistía en predicar de forma itinerante por los «pueblos» de la región, asentamientos demasiado grandes para ser simples aldeas pero sin alcanzar la categoría de πόλεις (ciudades). Estos pueblos con mercado servían como centros regionales para las zonas agrícolas circundantes. Jesús llevó el mensaje del reino a estos núcleos de población.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (71323, 'spa', 'Orgía y desenfreno', 'Fiesta desenfrenada, orgía o parranda con borrachera. Pablo enumera esta conducta entre las «obras de la carne» en Gálatas 5:21, advirtiendo que quienes la practican no heredarán el reino de Dios. Romanos 13:13 contrasta el caminar honroso «como de día» frente a entregarse al desenfreno y la embriaguez. 1 Pedro 4:3 la incluye entre los hábitos paganos que los creyentes han dejado atrás.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (71324, 'spa', 'Mosquito o jején', 'La crítica hiperbólica de Jesús al legalismo farisaico emplea el contraste mosquito-camello con efecto devastador. Los mosquitos eran insectos diminutos que se colaban del agua; los camellos, los animales más grandes de la región. Ambos eran ceremonialmente impuros, lo que hace funcionar la imagen. Lo absurdo radica en la proporción: filtrar insectos microscópicos mientras se tragan enormidades morales.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (71325, 'spa', 'Isla de Cos', 'En el relato de viaje de Lucas, Cos aparece como escala en el recorrido de Pablo desde Filipos hasta Jerusalén. La isla era célebre en la antigüedad por su escuela de medicina y el culto a Asclepio. La precisión de Lucas al registrar estas etapas sugiere memoria de testigo ocular. Cos era un fondeadero lógico para pernoctar.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (71326, 'spa', 'Nombre propio bíblico', 'Este nombre propio aparece una sola vez en Lucas 3:28, como parte de la genealogía ascendente que traza el linaje de Jesús hasta Adán. La evidencia multilingüe lo trata consistentemente como un nombre personal transliterado, con ligeras variaciones en la vocalización según las distintas tradiciones lingüísticas, reflejando diferentes enfoques para transcribir nombres griegos.');